@@ -118,6 +118,33 @@ function isIdentifierUsedBetweenAssignedAndEqualSign(assignment, identifier) {
 	);
 }

+/**
+ * Checks whether the value of the given update expression is used.
+ * @param {ASTNode} node The update expression or sequence expression to check.
+ * @returns {boolean} `true` if the update expression value is used.
+ */
+function isUpdateExpressionValueUsed(node) {
+	const parent = node.parent;
+
+	if (parent.type === "ExpressionStatement") {
+		return false;
+	}
+	if (parent.type === "ForStatement" && node === parent.update) {
+		return false;
+	}
+	if (parent.type === "SequenceExpression") {
+		return (
+			parent.expressions.at(-1) === node &&
+			isUpdateExpressionValueUsed(parent)
+		);
+	}
+	if (parent.type === "UnaryExpression" && parent.operator === "void") {
+		return false;
+	}
+
+	return true;
+}
+
 //------------------------------------------------------------------------------
 // Rule Definition
 //------------------------------------------------------------------------------
@@ -560,6 +587,9 @@ module.exports = {
 					expression = node.right;
 				} else {
 					// UpdateExpression
+					if (node.prefix && isUpdateExpressionValueUsed(node)) {
+						return;
+					}
 					pattern = node.argument;
 				}

